def run(fam, nl, nstart=25, seed=2):
    rng=np.random.default_rng(seed)
    def resid(q):
        B=fam(q)
        A=np.column_stack(B); A=np.where(np.isfinite(A),A,1e6)
        c,_,_,_=np.linalg.lstsq(A,s,rcond=None)
        r=A@c-s
        return np.where(np.isfinite(r),r,1e3)
    best=(np.inf,None)
